extern "C" int strlen(const char *);

class string_buf
{
  char gap[8];
public:
  int char_length;
};

class stringx
{
  char *chars;
  string_buf *my_buf;
public:
  stringx();
  stringx(const stringx &);
  stringx(const char *, int = -1);
  ~stringx();
  void append(const char *, int = -1);
  void append(const stringx &);
  void make_room(int);

  friend stringx operator+(const char *, const stringx &);
};

inline stringx operator+(const char *lhs, const stringx &rhs)
{
  stringx foo;
  int len = strlen(lhs);
  foo.make_room(len + rhs.my_buf->char_length);
  foo.append(lhs, len);
  foo.append(rhs);
  return foo;
}

class vm_thread
{
public:
  void slf_error(const stringx &);
};

class vm_stack
{
  int salloc;
  char *buffer;
  char *SP;
  vm_thread *my_thread;
public:
  char *get_SP() const { return SP; }
  vm_thread *get_thread() const { return my_thread; }
  void pop(int n) { SP -= n; }
};

class script_library_class
{
public:
  class function
  {
  public:
    enum entry_t { FIRST_ENTRY, RECALL_ENTRY };
    virtual ~function();
    virtual bool operator()(vm_stack &, entry_t) { return true; }
  };
};

class entity_track_tree
{
public:
  static const char *extension();
};

class ett_manager
{
public:
  bool load(const stringx &);
};

class world_dynamics_system
{
public:
  ett_manager *get_ett_manager();
};

extern world_dynamics_system *g_world_ptr;
bool file_finder_exists(const stringx &, const stringx &, stringx * = 0);
typedef const stringx *vm_str_t;

class slf_load_anim_t : public script_library_class::function
{
public:
  struct parms_t
  {
    vm_str_t filename;
  };

  virtual bool operator()(vm_stack &stack, entry_t entry)
  {
    stack.pop(sizeof(parms_t));
    parms_t *parms = (parms_t *)stack.get_SP();
    stringx fname;
    if (file_finder_exists(*parms->filename, entity_track_tree::extension(), &fname))
      g_world_ptr->get_ett_manager()->load(fname);
    else
      stack.get_thread()->slf_error("load_anim(): couldn't find " + *parms->filename);
    return true;
  }
};
